// @ts-nocheck
/* eslint-disable */
/**
 * TsPhone — dial codes (phoneCountryCode) and phone number masks (phoneNumberFormat). Rules in the header of the Java file.
 * GENERATED by tools/sync-java-dom.mjs from web/resources/js/phone_format.js — do not edit; change the script and run `npm run dom:sync`.
 *
 * The Java script, same behaviour line by line (ES5 written for a browser global scope — hence "@ts-nocheck": typing it
 * would change it, not port it). What differs from the original lives in tools/sync-java-dom.mjs:
 *   - it is a factory (createTsPhone) instead of window.TsPhone: DomGuards / PhoneFormat expose the instance as window.TsPhone
 *   -   for pages that were generated from Java, and typed access is through the PhoneFormat service;
 *   - the BFF base and fetch come from env (the script used to read its own <script src> and window.fetch).
 */

export interface TsPhoneEntry {
  country: string;
  phone: string;
  fmt: string;
}
export interface TsPhoneState {
  byCountry: Record<string, TsPhoneEntry>;
  entries: TsPhoneEntry[];
  validPhones: Record<string, boolean>;
  countries: Record<string, boolean>;
}
export interface TsPhoneResolved {
  phone: string;
  country: string;
  pick: string;
  fmt: string;
}
export interface TsPhone {
  readonly DEFAULT_COUNTRY: string;
  readonly DEFAULT_PHONE: string;
  load: () => Promise<TsPhoneState>;
  setCountries: (list: readonly unknown[]) => TsPhoneState;
  isReady: () => boolean;
  entries: () => TsPhoneEntry[];
  digits: (value: unknown) => string;
  maskGroups: (fmt: string | null | undefined) => number[];
  digitCount: (fmt: string | null | undefined) => number;
  format: (num: string, fmt: string | null | undefined, trimFront?: boolean) => string;
  applyInput: (el: HTMLInputElement | HTMLTextAreaElement | null, fmt: string | null | undefined, keepCaret?: boolean) => void;
  phoneExists: (phone: unknown) => boolean;
  countryExists: (countryCode: unknown) => boolean;
  phoneOfCountry: (countryCode: unknown) => string;
  formatOfCountry: (countryCode: unknown) => string;
  pickCountry: (phone: unknown, countryCode: unknown) => string;
  resolve: (phoneCountryCode: unknown, countryCode: unknown) => TsPhoneResolved;
  display: (tel: unknown, phoneCountryCode?: unknown, countryCode?: unknown) => string;
  html: (tel: unknown, phoneCountryCode?: unknown, countryCode?: unknown) => string;
  refresh: (root?: ParentNode | Document) => void;
}

export interface TsPhoneEnv {
  /** BFF base, e.g. "/triplesale" (Java: derived from the script URL) */
  apiBase: string;
  /** window.fetch in live mode, the fake master data in dev */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
}

export function createTsPhone(env: TsPhoneEnv): TsPhone {
    var d = document;

    var DEFAULT_COUNTRY = 'THA';
    var DEFAULT_PHONE = '+66';
    var EMPTY = {byCountry: {}, entries: [], validPhones: {}, countries: {}};

    /* context path จาก src ของไฟล์นี้เอง (…/triplesale/resources/js/phone_format.js → …/triplesale) */
    var CONTEXT = env.apiBase;

    var state = null;     /* null = ยังไม่มี master */
    var loading = null;   /* Promise ของ load() กันยิงซ้ำ */

    function trim(s) { return String(s == null ? '' : s).trim(); }
    function upper(s) { return trim(s).toUpperCase(); }
    function dial(s) { var t = trim(s); return /^\+?\d+$/.test(t) ? '+' + t.replace(/^\+/, '') : t; }
    function escHtml(s) {
        return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    /* ── ค่าที่เก็บ/ส่ง backend ── */
    /* ตัดทุกอักขระที่ไม่ใช่ตัวเลขทิ้ง ("81-234-5678" / "81 234 5678" → "812345678") — ตัวคั่นเป็นแค่การแสดงผล
       ใช้ตอน save ทุกครั้ง ; รหัสโทรไม่ได้ต่อรวมในเบอร์ ส่งแยกเป็น field phoneCountryCode */
    function digits(value) {
        return String(value == null ? '' : value).replace(/[^0-9]/g, '');
    }

    /* ── รูปแบบเบอร์ ── */
    function maskGroups(fmt) {
        var groups = [];
        var chunks = String(fmt || '').split(' / ')[0].split(' ');
        for (var i = 0; i < chunks.length; i++) {
            var n = (chunks[i].match(/X/gi) || []).length;
            if (n > 0) { groups.push(n); }
        }
        return groups;
    }
    function digitCount(fmt) {
        return maskGroups(fmt).reduce(function (a, n) { return a + n; }, 0);
    }
    /* trimFront=true → ค่าจาก DB ยาวเกินตัดข้างหน้า ; false → ระหว่างพิมพ์ ครบแล้วตัดตัวท้ายที่เกิน */
    function format(num, fmt, trimFront) {
        var groups = maskGroups(fmt);
        if (!groups.length || !num) { return num; }
        var total = digitCount(fmt);
        if (num.length > total) {
            num = trimFront ? num.substring(num.length - total) : num.substring(0, total);
        }
        var out = [], i = 0;
        for (var k = 0; k < groups.length && i < num.length; k++) {
            out.push(num.substr(i, groups[k]));
            i += groups[k];
        }
        return out.join('-');
    }
    /* จัดรูปแบบค่าใน input — keepCaret (ผู้ใช้พิมพ์เอง) คง cursor ตาม "จำนวนหลัก" ก่อน cursor
       ไม่ใช่ตำแหน่งตัวอักษร (ตัวคั่นที่แทรกเข้ามาทำให้ cursor กระโดด) */
    function applyInput(el, fmt, keepCaret) {
        if (!el) { return; }
        var raw = el.value == null ? '' : String(el.value);
        var caret = (keepCaret && el.selectionStart != null) ? el.selectionStart : raw.length;
        var digitsBeforeCaret = digits(raw.substring(0, caret)).length;
        var next = format(digits(raw), fmt, !keepCaret);
        if (next === raw) { return; }
        el.value = next;
        if (!keepCaret) { return; }
        var pos = 0, seen = 0;
        var maxDigits = digits(next).length;
        if (digitsBeforeCaret > maxDigits) { digitsBeforeCaret = maxDigits; }
        while (pos < next.length && seen < digitsBeforeCaret) {
            if (next.charAt(pos) >= '0' && next.charAt(pos) <= '9') { seen++; }
            pos++;
        }
        try { el.setSelectionRange(pos, pos); } catch (ignore) { }
    }

    /* ── master ประเทศ ── */
    function setCountries(list) {
        var s = {byCountry: {}, entries: [], validPhones: {}, countries: {}};
        (Array.isArray(list) ? list : []).forEach(function (c) {
            var cc = c && c.code ? upper(c.code) : '';
            if (!cc) { return; }
            s.countries[cc] = true;
            var phone = c.phoneCountryCode ? dial(c.phoneCountryCode) : '';
            if (!phone) { return; }   /* ประเทศไม่มีรหัสโทร (000/ASN/ATA) — ยังนับเป็นประเทศที่มีจริง */
            var it = {country: cc, phone: phone, fmt: c.phoneNumberFormat ? String(c.phoneNumberFormat) : ''};
            s.byCountry[cc] = it;
            s.validPhones[phone] = true;
            s.entries.push(it);
        });
        /* เรียงตามตัวเลขรหัสโทร แล้วตามรหัสประเทศ (= ลำดับ dropdown รหัสโทรของ lead_detail) */
        var num = function (it) { return parseInt(it.phone.replace(/[^0-9]/g, ''), 10) || 0; };
        s.entries.sort(function (a, b) {
            return (num(a) - num(b)) || (a.country < b.country ? -1 : a.country > b.country ? 1 : 0);
        });
        state = s;
        if (!loading) { loading = Promise.resolve(s); }
        refresh();
        return s;
    }
    /* ยิง master ครั้งเดียวต่อหน้า (ยิงไม่ติด = master ว่าง → ทุกเบอร์ได้ +66 ไม่มีรูปแบบ) */
    function load() {
        if (loading) { return loading; }
        if (!env.fetch) { return (loading = Promise.resolve(setCountries([]))); }
        loading = env.fetch(CONTEXT + '/board/chat-master-data?type=countries', {credentials: 'same-origin'})
            .then(function (r) { return r.ok ? r.json() : null; })
            .catch(function () { return null; })
            .then(function (res) {
                var list = (res && Array.isArray(res.result)) ? res.result : (Array.isArray(res) ? res : []);
                return setCountries(list);
            });
        return loading;
    }
    function S() { return state || EMPTY; }

    function isReady() { return !!state; }
    function entries() { return S().entries.slice(); }
    function phoneExists(phone) { phone = dial(phone); return !!phone && !!S().validPhones[phone]; }
    function countryExists(countryCode) { var cc = upper(countryCode); return !!cc && !!S().countries[cc]; }
    function phoneOfCountry(countryCode) { var it = S().byCountry[upper(countryCode)]; return it ? it.phone : ''; }
    function formatOfCountry(countryCode) { var it = S().byCountry[upper(countryCode)]; return it ? it.fmt : ''; }

    /* ประเทศที่ใช้กำหนดรูปแบบของรหัสโทรนี้ (กติกา 4) — ไม่มีประเทศไหนใช้รหัสนี้ = '' */
    function pickCountry(phone, countryCode) {
        phone = dial(phone);
        var cc = upper(countryCode);
        var own = S().byCountry[cc];
        if (own && own.phone === phone) { return cc; }
        var pick = '', best = -1;
        S().entries.forEach(function (it) {
            if (it.phone !== phone) { return; }
            var n = digitCount(it.fmt);
            if (n > best) { best = n; pick = it.country; }
        });
        return pick;
    }
    /* รหัสโทรของ lead/prospect (กติกา 3) → {phone:"+66", country:"THA", pick:"THA", fmt:"XX XXX XXXX"}
       country = ประเทศที่ผ่าน validate แล้ว (ไม่มี/มั่ว → THA), pick = ประเทศที่ให้รูปแบบ ('' = ไม่มีรูปแบบ) */
    function resolve(phoneCountryCode, countryCode) {
        var own = phoneExists(phoneCountryCode) ? dial(phoneCountryCode) : '';
        var cc = countryExists(countryCode) ? upper(countryCode) : DEFAULT_COUNTRY;
        var phone = own || phoneOfCountry(cc) || DEFAULT_PHONE;
        var pick = pickCountry(phone, cc);
        return {phone: phone, country: cc, pick: pick, fmt: pick ? formatOfCountry(pick) : ''};
    }

    /* ── แสดงผลอย่างเดียว (ตาราง/การ์ด) ── */
    /* "+66 81-234-5678" ; ไม่มีเบอร์ = "-" (ไม่โชว์รหัสลอยๆ) ; master ยังไม่มา = เลขดิบไปก่อน */
    function display(tel, phoneCountryCode, countryCode) {
        var raw = trim(tel);
        if (!state) { return raw || '-'; }
        var num = digits(raw);
        if (!num) { return '-'; }
        var phone = dial(phoneCountryCode);
        if (!phone) { return num; }
        var pick = pickCountry(phone, countryCode);
        var fmt = pick ? formatOfCountry(pick) : '';
        return phone + ' ' + (fmt ? format(num, fmt, true) : num);
    }
    /* span ที่ refresh() อัปเดตเองเมื่อ master มาถึง — ใช้แทนการต่อ string เบอร์ตรงๆ ใน template ของหน้า */
    function html(tel, phoneCountryCode, countryCode) {
        return '<span class="ts-tel" data-tel="' + escHtml(trim(tel)) + '" data-pcc="' + escHtml(trim(phoneCountryCode))
            + '" data-cc="' + escHtml(trim(countryCode)) + '">' + escHtml(display(tel, phoneCountryCode, countryCode)) + '</span>';
    }
    function refresh(root) {
        var scope = root || d;
        if (!scope.querySelectorAll) { return; }
        var list = scope.querySelectorAll('.ts-tel');
        for (var i = 0; i < list.length; i++) {
            var el = list[i];
            el.textContent = display(el.getAttribute('data-tel'), el.getAttribute('data-pcc'), el.getAttribute('data-cc'));
        }
    }

    var api = {
        DEFAULT_COUNTRY: DEFAULT_COUNTRY,
        DEFAULT_PHONE: DEFAULT_PHONE,
        load: load,
        setCountries: setCountries,
        isReady: isReady,
        entries: entries,
        digits: digits,
        maskGroups: maskGroups,
        digitCount: digitCount,
        format: format,
        applyInput: applyInput,
        phoneExists: phoneExists,
        countryExists: countryExists,
        phoneOfCountry: phoneOfCountry,
        formatOfCountry: formatOfCountry,
        pickCountry: pickCountry,
        resolve: resolve,
        display: display,
        html: html,
        refresh: refresh
    };
    return api;
}
